sp_widget.client_script:
api.controller = function($scope, $http, $timeout) {
  /* KYC Capture Widget Controller */
  var c = this;
  var video, canvas, stream;

  // --- Initialize ---
  c.data.cameraActive = false;
  c.data.currentStep = 0;
  c.data.allCaptured = false;
  c.data.photos = {
    id_front_page: null,
    id_back_page: null,
    selfie_picture: null
  };

  c.data.captureSteps = [
    { field: 'id_front_page', label: 'ID Front Page' },
    { field: 'id_back_page', label: 'ID Back Page' },
    { field: 'selfie_picture', label: 'Selfie Picture' }
  ];

  // --- Start Camera ---
  c.startCapture = function() {
    c.data.cameraActive = true;

    // Wait for DOM to render <video> before accessing it
    $timeout(function() {
      video = document.getElementById('video');
      canvas = document.getElementById('canvas');

      if (!video) {
        alert('Video element not found. Please try again.');
        return;
      }

      if (navigator.mediaDevices && navigator.mediaDevices.getUserMedia) {
        navigator.mediaDevices.getUserMedia({ video: true })
          .then(function(s) {
            stream = s;
            video.srcObject = s;
          })
          .catch(function(err) {
            alert('Error accessing camera: ' + err);
          });
      } else {
        alert('Your browser does not support camera access.');
      }
    }, 300); // Wait for Angular to render DOM
  };

  // --- Capture Photo ---
  c.capturePhoto = function() {
    if (!video) {
      alert('Camera not ready.');
      return;
    }

    canvas.width = video.videoWidth;
    canvas.height = video.videoHeight;
    var ctx = canvas.getContext('2d');
    ctx.drawImage(video, 0, 0, canvas.width, canvas.height);

    var imageData = canvas.toDataURL('image/png');
    var currentField = c.data.captureSteps[c.data.currentStep].field;
    c.data.photos[currentField] = imageData;

    if (c.data.currentStep < c.data.captureSteps.length - 1) {
      c.data.currentStep++;
    } else {
      c.data.allCaptured = true;
      c.stopCamera();
    }

    $scope.$applyAsync();
  };

  // --- Stop Camera ---
  c.stopCamera = function() {
    if (stream) {
      var tracks = stream.getTracks();
      for (var i = 0; i < tracks.length; i++) {
        tracks[i].stop();
      }
    }
    c.data.cameraActive = false;
  };

  // --- Save Photos to Server ---
  c.savePhotos = function() {
    c.server.update({
      photos: c.data.photos
    }).then(function(response) {
      if (response.data.status === 'success') {
        alert('Photos saved successfully!');

        // Optional: reset widget
        c.data.allCaptured = false;
        c.data.currentStep = 0;
        c.data.photos = {
          id_front_page: null,
          id_back_page: null,
          selfie_picture: null
        };
      } else {
        alert('Error saving photos. Please check the logs.');
      }
    });
  };
};

sp_widget.css:
.kyc-widget {
  padding: 20px;
  background: #fff;
  border-radius: 12px;
  box-shadow: 0 2px 8px rgba(0,0,0,0.1);
}

video {
  width: 100%;
  max-width: 400px;
  border: 2px solid #ddd;
  border-radius: 8px;
}

.preview-images img {
  width: 120px;
  margin: 8px;
  border: 2px solid #ccc;
  border-radius: 8px;
}

.hidden {
  display: none;
}

sp_widget.script:
(function() {
  var response = {}; // Object to hold response status/action
  try {
    var userEmail = gs.getUser().getEmail(); // Retrieve logged-in user's email
    gs.info('KYC Widget Debug: User email - ' + userEmail);

    // Function to convert attachment bytes to Base64 string
    var getAttachmentBase64 = function(attachmentSysId) {
      if (!attachmentSysId) return ''; // Exit if no Sys ID provided
      try {
        var attachment = new GlideSysAttachment(); // Attachment handler
        var bytes = attachment.getBytes(attachmentSysId); // Get file bytes

        if (!bytes) {
          gs.info('KYC Widget Debug: No bytes found for attachment ' + attachmentSysId);
          return ''; // No file data
        }

        var base64String = GlideBase64.encode(bytes); // Convert bytes to Base64
        gs.info('KYC Widget Debug: Encoded attachment ' + attachmentSysId + ' to Base64, length: ' + base64String.length);
        return base64String;
      } catch (err) {
        gs.error('KYC Widget Debug: Error encoding attachment ' + attachmentSysId + ' - ' + err.message);
        return ''; // Return empty string on failure
      }
    };

    // Process photos sent from widget
    if (input && input.photos) {
      var glideRecordIndividual = new GlideRecordSecure('x_vuram_financia_0_fcc_kyc_individual_details'); // KYC table
      glideRecordIndividual.addQuery('email', userEmail); // Match record with user email
      glideRecordIndividual.query();

      // Update existing record
      if (glideRecordIndividual.next()) {
        glideRecordIndividual.setValue('id_front_page', input.photos.id_front_page); // Store front side
        glideRecordIndividual.setValue('id_back_page', input.photos.id_back_page); // Store back side
        glideRecordIndividual.setValue('video_recording', input.photos.selfie_picture); // Selfie capture
        glideRecordIndividual.update(); // Save changes

        gs.info('KYC Widget Info: Photos successfully inserted for user ' + userEmail);
        data.status = 'success';
        data.action = 'updated';

      } else { // Create new record if none exists
        glideRecordIndividual.initialize(); // Prepare new record
        glideRecordIndividual.setValue('email', userEmail); // Set email
        glideRecordIndividual.setValue('id_front_page', input.photos.id_front_page);
        glideRecordIndividual.setValue('id_back_page', input.photos.id_back_page);
        glideRecordIndividual.setValue('video_recording', input.photos.selfie_picture);
        glideRecordIndividual.insert(); // Insert new record

        data.status = 'success';
        data.action = 'inserted';
      }

    } else {
      // Handle scenario where photos are not provided
      gs.info('KYC Widget Debug: No photos found in input');
      response.status = 'waiting';
      response.action = 'none';
    }

  } catch (e) {
    // Global error handling
    gs.error('KYC Widget Error: ' + e.message);
    response.status = 'error';
    response.action = 'none';
  }

  // Final output values
  data.status = response.status || 'waiting';
  data.action = response.action || 'none';
})();
